sql.where:
game_type = 'zyjdc'

    AND game_id = #{q.gameId}


    AND instance_id = #{q.instanceId}


    AND school_id = #{q.schoolId}


    AND (department_id = #{q.departmentId}
         OR EXISTS (SELECT 1 FROM gkzh_school_department d
                    WHERE d.department_id = gkzh_zyjdc_record.department_id
                      AND FIND_IN_SET(#{q.departmentId}, d.ancestors)))


    AND major LIKE CONCAT('%', #{q.major}, '%')


    AND student_no LIKE CONCAT('%', #{q.studentNo}, '%')


    AND gender IN ('男', '0')


    AND gender IN ('女', '1')


    AND (gender IS NULL OR TRIM(gender) = '' OR gender NOT IN ('男', '0', '女', '1'))


    AND role_id = #{q.roleId}


    AND result = #{q.result}


    AND status = #{q.status}


    AND scan_time >= #{q.startDate}


    AND scan_time < #{q.endDate}

mapper.select:
SELECT * FROM gkzh_zyjdc_record
WHERE game_type = 'zyjdc' AND game_id = #{gameId}
ORDER BY record_id DESC
LIMIT #{limit}
